"use strict";document.body.addEventListener("htmx:after-swap",function(evt){let el=evt.target;if(el.id!="rc-swap")return;el.childNodes.forEach(function(child){let selector=child.getAttribute("rc-swap");if(!selector)return;let targets=document.querySelectorAll("[rc-swap='"+selector+"']");targets.forEach((oldEl)=>{if(oldEl===child)return;console.log(oldEl);oldEl.replaceWith(child.cloneNode(!0))})});el.remove()})